// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, uint256 fund) public {
        fund = bound(fund, 0, 1 ether);

        vm.deal(address(this), fund);
        (bool s, ) = address(c).call{value: fund}("");
        require(s);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(address(uint160(uint256(keccak256(abi.encodePacked(caller, "dest")))))) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == address(this)));
    }
}
